// Sandbox-friendly stand-in demonstrating bounded waiting semantics.
fn slow_square(n: u64) -> u64 {
    std::thread::sleep(std::time::Duration::from_millis(n));
    n * n
}

fn main() {
    let started = std::time::Instant::now();
    let values = [10u64, 20, 30];
    let results: Vec<u64> = values.iter().map(|&n| slow_square(n)).collect();
    println!("{:?} in {:?}", results, started.elapsed());
}

