fn with_deadline(limit_ms: u64, work_ms: u64) -> &'static str {
    if work_ms <= limit_ms {
        "done"
    } else {
        "timeout"
    }
}

fn main() {
    println!("{}", with_deadline(50, 30));
    println!("{}", with_deadline(50, 120));
}
